import{_ as t,o as d,c as e,Q as a}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"200 Useful Maltese Phrases","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/grammar/02-phrases.md","filePath":"en/more/maltese/grammar/02-phrases.md"}'),r={name:"en/more/maltese/grammar/02-phrases.md"},i=a('<h1 id="_200-useful-maltese-phrases" tabindex="-1">200 Useful Maltese Phrases <a class="header-anchor" href="#_200-useful-maltese-phrases" aria-label="Permalink to &quot;200 Useful Maltese Phrases&quot;">​</a></h1><p>The phrases are grouped into ten situations, with 20 examples per category. Numbering restarts in each section. Some expressions change according to the listener&#39;s gender, number, or context; ellipses can be replaced with specific information.</p><h2 id="greetings-and-farewells" tabindex="-1">Greetings and Farewells <a class="header-anchor" href="#greetings-and-farewells" aria-label="Permalink to &quot;Greetings and Farewells&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>Hello; good morning</td><td>Bonġu</td></tr><tr><td style="text-align:right;">2</td><td>Good morning</td><td>L-għodwa t-tajba</td></tr><tr><td style="text-align:right;">3</td><td>Good afternoon</td><td>Wara nofsinhar it-tajjeb</td></tr><tr><td style="text-align:right;">4</td><td>Good evening</td><td>Bonswa</td></tr><tr><td style="text-align:right;">5</td><td>Good night</td><td>Il-lejl it-tajjeb</td></tr><tr><td style="text-align:right;">6</td><td>Goodbye</td><td>Saħħa</td></tr><tr><td style="text-align:right;">7</td><td>Bye</td><td>Ċaw</td></tr><tr><td style="text-align:right;">8</td><td>Welcome</td><td>Merħba</td></tr><tr><td style="text-align:right;">9</td><td>How are you? (one person)</td><td>Kif int?</td></tr><tr><td style="text-align:right;">10</td><td>How are you? (plural)</td><td>Kif intom?</td></tr><tr><td style="text-align:right;">11</td><td>Have a nice day</td><td>Il-ġurnata t-tajba</td></tr><tr><td style="text-align:right;">12</td><td>See you later</td><td>Narawk aktar tard</td></tr><tr><td style="text-align:right;">13</td><td>See you soon</td><td>Narawk dalwaqt</td></tr><tr><td style="text-align:right;">14</td><td>See you tomorrow</td><td>Narawk għada</td></tr><tr><td style="text-align:right;">15</td><td>Welcome to Malta</td><td>Merħba f&#39;Malta</td></tr><tr><td style="text-align:right;">16</td><td>Is everything all right?</td><td>Kollox sew?</td></tr><tr><td style="text-align:right;">17</td><td>Good morning, how are you?</td><td>Bonġu, kif int?</td></tr><tr><td style="text-align:right;">18</td><td>Good evening, welcome</td><td>Bonswa, merħba</td></tr><tr><td style="text-align:right;">19</td><td>Take care</td><td>Ħu ħsiebek</td></tr><tr><td style="text-align:right;">20</td><td>How was your day?</td><td>Kif kienet il-ġurnata tiegħek?</td></tr></tbody></table><h2 id="polite-expressions-and-responses" tabindex="-1">Polite Expressions and Responses <a class="header-anchor" href="#polite-expressions-and-responses" aria-label="Permalink to &quot;Polite Expressions and Responses&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>Please</td><td>Jekk jogħġbok</td></tr><tr><td style="text-align:right;">2</td><td>Thank you</td><td>Grazzi</td></tr><tr><td style="text-align:right;">3</td><td>Thank you very much</td><td>Grazzi ħafna</td></tr><tr><td style="text-align:right;">4</td><td>You&#39;re welcome; don&#39;t mention it</td><td>M&#39;hemmx għalfejn</td></tr><tr><td style="text-align:right;">5</td><td>I&#39;m sorry</td><td>Jiddispjaċini</td></tr><tr><td style="text-align:right;">6</td><td>Excuse me; forgive me</td><td>Skużani</td></tr><tr><td style="text-align:right;">7</td><td>Yes</td><td>Iva</td></tr><tr><td style="text-align:right;">8</td><td>No</td><td>Le</td></tr><tr><td style="text-align:right;">9</td><td>No problem</td><td>Mhux problema</td></tr><tr><td style="text-align:right;">10</td><td>All right; okay</td><td>Tajjeb</td></tr><tr><td style="text-align:right;">11</td><td>Thank you for your help</td><td>Grazzi tal-għajnuna tiegħek</td></tr><tr><td style="text-align:right;">12</td><td>Please come in</td><td>Idħol, jekk jogħġbok</td></tr><tr><td style="text-align:right;">13</td><td>Please sit down</td><td>Oqgħod bilqiegħda, jekk jogħġbok</td></tr><tr><td style="text-align:right;">14</td><td>Please wait a little</td><td>Stenna ftit, jekk jogħġbok</td></tr><tr><td style="text-align:right;">15</td><td>One moment</td><td>Stenna mument</td></tr><tr><td style="text-align:right;">16</td><td>It&#39;s all right</td><td>Sewwa</td></tr><tr><td style="text-align:right;">17</td><td>Please forgive me</td><td>Aħfirli, jekk jogħġbok</td></tr><tr><td style="text-align:right;">18</td><td>Thank you for your time</td><td>Grazzi tal-ħin tiegħek</td></tr><tr><td style="text-align:right;">19</td><td>Don&#39;t worry</td><td>Tinkwetax</td></tr><tr><td style="text-align:right;">20</td><td>I appreciate it</td><td>Napprezzaha</td></tr></tbody></table><h2 id="introducing-yourself-and-meeting-people" tabindex="-1">Introducing Yourself and Meeting People <a class="header-anchor" href="#introducing-yourself-and-meeting-people" aria-label="Permalink to &quot;Introducing Yourself and Meeting People&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>What is your name?</td><td>X&#39;jismek?</td></tr><tr><td style="text-align:right;">2</td><td>My name is ...</td><td>Jisimni ...</td></tr><tr><td style="text-align:right;">3</td><td>I am ...</td><td>Jien ...</td></tr><tr><td style="text-align:right;">4</td><td>Where are you from?</td><td>Minn fejn int?</td></tr><tr><td style="text-align:right;">5</td><td>I am from ...</td><td>Jien minn ...</td></tr><tr><td style="text-align:right;">6</td><td>Where do you live?</td><td>Fejn toqgħod?</td></tr><tr><td style="text-align:right;">7</td><td>I live in ...</td><td>Noqgħod f&#39;...</td></tr><tr><td style="text-align:right;">8</td><td>How old are you?</td><td>Kemm għandek żmien?</td></tr><tr><td style="text-align:right;">9</td><td>I am ... years old</td><td>Għandi ... sena / snin</td></tr><tr><td style="text-align:right;">10</td><td>Nice to meet you</td><td>Għandi pjaċir</td></tr><tr><td style="text-align:right;">11</td><td>I am from China</td><td>Jien miċ-Ċina</td></tr><tr><td style="text-align:right;">12</td><td>I live in Malta</td><td>Noqgħod Malta</td></tr><tr><td style="text-align:right;">13</td><td>I am a student</td><td>Jien student / studentessa</td></tr><tr><td style="text-align:right;">14</td><td>I am a teacher</td><td>Jien għalliem / għalliema</td></tr><tr><td style="text-align:right;">15</td><td>I am learning Maltese</td><td>Qed nitgħallem il-Malti</td></tr><tr><td style="text-align:right;">16</td><td>What languages do you speak?</td><td>Liema lingwi titkellem?</td></tr><tr><td style="text-align:right;">17</td><td>Do you live here?</td><td>Toqgħod hawn?</td></tr><tr><td style="text-align:right;">18</td><td>What do you do for work?</td><td>X&#39;tagħmel?</td></tr><tr><td style="text-align:right;">19</td><td>I work in Valletta</td><td>Naħdem il-Belt</td></tr><tr><td style="text-align:right;">20</td><td>We are friends</td><td>Aħna ħbieb</td></tr></tbody></table><h2 id="everyday-conversation-and-language" tabindex="-1">Everyday Conversation and Language <a class="header-anchor" href="#everyday-conversation-and-language" aria-label="Permalink to &quot;Everyday Conversation and Language&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>Do you speak English?</td><td>Titkellem bl-Ingliż?</td></tr><tr><td style="text-align:right;">2</td><td>I speak a little Maltese</td><td>Nitkellem ftit bil-Malti</td></tr><tr><td style="text-align:right;">3</td><td>I don&#39;t understand</td><td>Ma nifhimx</td></tr><tr><td style="text-align:right;">4</td><td>Please say it again</td><td>Erġa&#39; għidha, jekk jogħġbok</td></tr><tr><td style="text-align:right;">5</td><td>Please speak slowly</td><td>Tkellem bil-mod, jekk jogħġbok</td></tr><tr><td style="text-align:right;">6</td><td>What does this word mean?</td><td>Xi tfisser din il-kelma?</td></tr><tr><td style="text-align:right;">7</td><td>How do you say this in Maltese?</td><td>Kif tgħid dan bil-Malti?</td></tr><tr><td style="text-align:right;">8</td><td>How do you spell this?</td><td>Kif tinkiteb?</td></tr><tr><td style="text-align:right;">9</td><td>Can you help me?</td><td>Tista&#39; tgħinni?</td></tr><tr><td style="text-align:right;">10</td><td>I understand</td><td>Nifhem</td></tr><tr><td style="text-align:right;">11</td><td>I don&#39;t know</td><td>Ma nafx</td></tr><tr><td style="text-align:right;">12</td><td>I forgot this word</td><td>Insejt din il-kelma</td></tr><tr><td style="text-align:right;">13</td><td>Can you write it down?</td><td>Tista&#39; tiktebha?</td></tr><tr><td style="text-align:right;">14</td><td>Can you say it more slowly?</td><td>Tista&#39; tgħidha aktar bil-mod?</td></tr><tr><td style="text-align:right;">15</td><td>I am still learning</td><td>Għadni qed nitgħallem</td></tr><tr><td style="text-align:right;">16</td><td>I only speak a little</td><td>Nitkellem ftit biss</td></tr><tr><td style="text-align:right;">17</td><td>Please explain</td><td>Spjega, jekk jogħġbok</td></tr><tr><td style="text-align:right;">18</td><td>Can you repeat this word?</td><td>Tista&#39; tirrepeti din il-kelma?</td></tr><tr><td style="text-align:right;">19</td><td>Is this answer correct?</td><td>Din it-tweġiba hija tajba?</td></tr><tr><td style="text-align:right;">20</td><td>I can&#39;t hear clearly</td><td>Ma nistax nisma&#39; sew</td></tr></tbody></table><h2 id="restaurant-and-ordering-food" tabindex="-1">Restaurant and Ordering Food <a class="header-anchor" href="#restaurant-and-ordering-food" aria-label="Permalink to &quot;Restaurant and Ordering Food&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>Do you have a table for two?</td><td>Għandkom mejda għal tnejn?</td></tr><tr><td style="text-align:right;">2</td><td>May I see the menu?</td><td>Nista&#39; nara l-menu?</td></tr><tr><td style="text-align:right;">3</td><td>What do you recommend?</td><td>X&#39;tirrakkomanda?</td></tr><tr><td style="text-align:right;">4</td><td>I would like ...</td><td>Nixtieq ...</td></tr><tr><td style="text-align:right;">5</td><td>I&#39;ll have this</td><td>Se nieħu dan</td></tr><tr><td style="text-align:right;">6</td><td>Water, please</td><td>Ilma, jekk jogħġbok</td></tr><tr><td style="text-align:right;">7</td><td>A coffee, please</td><td>Kafè wieħed, jekk jogħġbok</td></tr><tr><td style="text-align:right;">8</td><td>I don&#39;t eat meat</td><td>Ma niekolx laħam</td></tr><tr><td style="text-align:right;">9</td><td>I am a vegetarian</td><td>Jien veġetarjan / veġetarjana</td></tr><tr><td style="text-align:right;">10</td><td>The bill, please</td><td>Il-kont, jekk jogħġbok</td></tr><tr><td style="text-align:right;">11</td><td>Do you have a table by the window?</td><td>Għandkom mejda ħdejn it-tieqa?</td></tr><tr><td style="text-align:right;">12</td><td>I am hungry</td><td>Għandi l-ġuħ</td></tr><tr><td style="text-align:right;">13</td><td>I am thirsty</td><td>Għandi l-għatx</td></tr><tr><td style="text-align:right;">14</td><td>Without sugar, please</td><td>Mingħajr zokkor, jekk jogħġbok</td></tr><tr><td style="text-align:right;">15</td><td>Without milk, please</td><td>Mingħajr ħalib, jekk jogħġbok</td></tr><tr><td style="text-align:right;">16</td><td>This dish is very good</td><td>Dan il-platt hu tajjeb ħafna</td></tr><tr><td style="text-align:right;">17</td><td>I am allergic to peanuts</td><td>Jien allerġiku / allerġika għall-karawett</td></tr><tr><td style="text-align:right;">18</td><td>Can I have another one?</td><td>Nista&#39; nieħu ieħor?</td></tr><tr><td style="text-align:right;">19</td><td>Is there any bread left?</td><td>Għad baqa&#39; ħobż?</td></tr><tr><td style="text-align:right;">20</td><td>A tea, please</td><td>Te wieħed, jekk jogħġbok</td></tr></tbody></table><h2 id="shopping-and-payment" tabindex="-1">Shopping and Payment <a class="header-anchor" href="#shopping-and-payment" aria-label="Permalink to &quot;Shopping and Payment&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>How much is this? (masculine noun)</td><td>Kemm jiswa dan?</td></tr><tr><td style="text-align:right;">2</td><td>How much is this? (feminine noun)</td><td>Kemm tiswa din?</td></tr><tr><td style="text-align:right;">3</td><td>I&#39;m just looking</td><td>Qed inħares biss</td></tr><tr><td style="text-align:right;">4</td><td>Do you have a larger size?</td><td>Għandek daqs akbar?</td></tr><tr><td style="text-align:right;">5</td><td>Do you have a smaller size?</td><td>Għandek daqs iżgħar?</td></tr><tr><td style="text-align:right;">6</td><td>Can I try this?</td><td>Nista&#39; nipprova dan?</td></tr><tr><td style="text-align:right;">7</td><td>I&#39;ll take this</td><td>Se nieħu dan</td></tr><tr><td style="text-align:right;">8</td><td>Can I pay by card?</td><td>Nista&#39; nħallas bil-karta?</td></tr><tr><td style="text-align:right;">9</td><td>A receipt, please</td><td>Irċevuta, jekk jogħġbok</td></tr><tr><td style="text-align:right;">10</td><td>Where is the checkout?</td><td>Fejn hi l-kassa?</td></tr><tr><td style="text-align:right;">11</td><td>Do you have another color?</td><td>Għandek kulur ieħor?</td></tr><tr><td style="text-align:right;">12</td><td>This is too expensive</td><td>Dan jiswa wisq</td></tr><tr><td style="text-align:right;">13</td><td>Is there a discount?</td><td>Hemm skont?</td></tr><tr><td style="text-align:right;">14</td><td>Do you accept cash?</td><td>Taċċettaw flus kontanti?</td></tr><tr><td style="text-align:right;">15</td><td>I will pay in cash</td><td>Se nħallas bi flus kontanti</td></tr><tr><td style="text-align:right;">16</td><td>I need a bag</td><td>Għandi bżonn borża</td></tr><tr><td style="text-align:right;">17</td><td>Where is the fitting room?</td><td>Fejn hi l-kamra tal-provi?</td></tr><tr><td style="text-align:right;">18</td><td>I&#39;m looking for ...</td><td>Qed infittex ...</td></tr><tr><td style="text-align:right;">19</td><td>Can I exchange this?</td><td>Nista&#39; nbiddel dan?</td></tr><tr><td style="text-align:right;">20</td><td>A receipt, please</td><td>Irċevuta, jekk jogħġbok</td></tr></tbody></table><h2 id="asking-for-directions-and-travelling" tabindex="-1">Asking for Directions and Travelling <a class="header-anchor" href="#asking-for-directions-and-travelling" aria-label="Permalink to &quot;Asking for Directions and Travelling&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>Where is ...?</td><td>Fejn hi ...?</td></tr><tr><td style="text-align:right;">2</td><td>Where is the train station?</td><td>Fejn jinsab l-istazzjon?</td></tr><tr><td style="text-align:right;">3</td><td>Where is the bus stop?</td><td>Fejn hi l-waqfa tal-karozzi tal-linja?</td></tr><tr><td style="text-align:right;">4</td><td>How do I get to the city centre?</td><td>Kif nasal sal-belt?</td></tr><tr><td style="text-align:right;">5</td><td>Go straight ahead</td><td>Mur dritt</td></tr><tr><td style="text-align:right;">6</td><td>Turn left</td><td>Dawwar fuq ix-xellug</td></tr><tr><td style="text-align:right;">7</td><td>Turn right</td><td>Dawwar fuq il-lemin</td></tr><tr><td style="text-align:right;">8</td><td>Is it near here?</td><td>Huwa qrib hawn?</td></tr><tr><td style="text-align:right;">9</td><td>Can you show me on the map?</td><td>Tista&#39; turini fuq il-mappa?</td></tr><tr><td style="text-align:right;">10</td><td>I&#39;m lost</td><td>Tlift</td></tr><tr><td style="text-align:right;">11</td><td>Where is the map?</td><td>Fejn hi l-mappa?</td></tr><tr><td style="text-align:right;">12</td><td>Is there a bank nearby?</td><td>Hemm bank fil-qrib?</td></tr><tr><td style="text-align:right;">13</td><td>I want to go to the airport</td><td>Irrid immur l-ajruport</td></tr><tr><td style="text-align:right;">14</td><td>Stop here, please</td><td>Waqqaf hawn, jekk jogħġbok</td></tr><tr><td style="text-align:right;">15</td><td>Does this bus go to Valletta?</td><td>Dan ix-xarabank imur il-Belt?</td></tr><tr><td style="text-align:right;">16</td><td>What time does the next bus leave?</td><td>X&#39;ħin jitlaq ix-xarabank li jmiss?</td></tr><tr><td style="text-align:right;">17</td><td>Where can I buy a ticket?</td><td>Fejn nista&#39; nixtri biljett?</td></tr><tr><td style="text-align:right;">18</td><td>Can you call a taxi?</td><td>Tista&#39; ċċempel taxi?</td></tr><tr><td style="text-align:right;">19</td><td>This place is near here</td><td>Dan il-post hu qrib hawn</td></tr><tr><td style="text-align:right;">20</td><td>Is this the way to the airport?</td><td>Din hi t-triq għall-ajruport?</td></tr></tbody></table><h2 id="time-and-arrangements" tabindex="-1">Time and Arrangements <a class="header-anchor" href="#time-and-arrangements" aria-label="Permalink to &quot;Time and Arrangements&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>What time is it?</td><td>X&#39;ħin hu?</td></tr><tr><td style="text-align:right;">2</td><td>At eight o&#39;clock</td><td>Fit-tmienja</td></tr><tr><td style="text-align:right;">3</td><td>At half past eight</td><td>Fit-tmienja u nofs</td></tr><tr><td style="text-align:right;">4</td><td>When does the bus leave?</td><td>Meta jitlaq ix-xarabank?</td></tr><tr><td style="text-align:right;">5</td><td>When will you arrive?</td><td>Meta tasal?</td></tr><tr><td style="text-align:right;">6</td><td>One ticket, please</td><td>Biljett wieħed, jekk jogħġbok</td></tr><tr><td style="text-align:right;">7</td><td>Where can I buy a ticket?</td><td>Fejn nista&#39; nixtri biljett?</td></tr><tr><td style="text-align:right;">8</td><td>Tomorrow morning</td><td>Għada filgħodu</td></tr><tr><td style="text-align:right;">9</td><td>This afternoon</td><td>Illum wara nofsinhar</td></tr><tr><td style="text-align:right;">10</td><td>See you tomorrow</td><td>Narawk għada</td></tr><tr><td style="text-align:right;">11</td><td>I am free today</td><td>Għandi l-ħin illum</td></tr><tr><td style="text-align:right;">12</td><td>I am busy tomorrow</td><td>Għada nkun impenjat / impenjata</td></tr><tr><td style="text-align:right;">13</td><td>What time does the meeting start?</td><td>X&#39;ħin tibda l-laqgħa?</td></tr><tr><td style="text-align:right;">14</td><td>What time does the shop close?</td><td>X&#39;ħin jagħlaq il-ħanut?</td></tr><tr><td style="text-align:right;">15</td><td>We will meet at five</td><td>Naraw lil xulxin fil-ħamsa</td></tr><tr><td style="text-align:right;">16</td><td>The bus is late</td><td>Ix-xarabank wasal tard</td></tr><tr><td style="text-align:right;">17</td><td>I will arrive in ten minutes</td><td>Nasal f&#39;għaxar minuti</td></tr><tr><td style="text-align:right;">18</td><td>What day is it today?</td><td>Liema jum hu llum?</td></tr><tr><td style="text-align:right;">19</td><td>See you on Monday</td><td>Naraw lil xulxin it-Tnejn</td></tr><tr><td style="text-align:right;">20</td><td>Please arrive on time</td><td>Wasal fil-ħin, jekk jogħġbok</td></tr></tbody></table><h2 id="everyday-needs" tabindex="-1">Everyday Needs <a class="header-anchor" href="#everyday-needs" aria-label="Permalink to &quot;Everyday Needs&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>Where is the toilet?</td><td>Fejn hi t-toilet?</td></tr><tr><td style="text-align:right;">2</td><td>Where is the bathroom?</td><td>Fejn hi l-kamra tal-banju?</td></tr><tr><td style="text-align:right;">3</td><td>I need water</td><td>Għandi bżonn ilma</td></tr><tr><td style="text-align:right;">4</td><td>I need internet access</td><td>Għandi bżonn l-internet</td></tr><tr><td style="text-align:right;">5</td><td>What is the Wi-Fi password?</td><td>X&#39;inhi l-password tal-Wi-Fi?</td></tr><tr><td style="text-align:right;">6</td><td>Can I use your phone?</td><td>Nista&#39; nuża t-telefon tiegħek?</td></tr><tr><td style="text-align:right;">7</td><td>Can you call a taxi?</td><td>Tista&#39; ċċempel taxi?</td></tr><tr><td style="text-align:right;">8</td><td>I need a map</td><td>Għandi bżonn mappa</td></tr><tr><td style="text-align:right;">9</td><td>Is everything all right?</td><td>Kollox sew?</td></tr><tr><td style="text-align:right;">10</td><td>I&#39;ll be right back</td><td>Nerġa&#39; niġi mill-ewwel</td></tr><tr><td style="text-align:right;">11</td><td>Where is the nearest supermarket?</td><td>Fejn hu l-eqreb supermarket?</td></tr><tr><td style="text-align:right;">12</td><td>Is there Wi-Fi?</td><td>Hemm Wi-Fi?</td></tr><tr><td style="text-align:right;">13</td><td>The room is very cold</td><td>Il-kamra hi kiesħa ħafna</td></tr><tr><td style="text-align:right;">14</td><td>Open the window, please</td><td>Iftaħ it-tieqa, jekk jogħġbok</td></tr><tr><td style="text-align:right;">15</td><td>Close the door, please</td><td>Agħlaq il-bieb, jekk jogħġbok</td></tr><tr><td style="text-align:right;">16</td><td>I need a charger</td><td>Għandi bżonn charger</td></tr><tr><td style="text-align:right;">17</td><td>I have a reservation</td><td>Għandi prenotazzjoni</td></tr><tr><td style="text-align:right;">18</td><td>Where is the reception desk?</td><td>Fejn hi r-reception?</td></tr><tr><td style="text-align:right;">19</td><td>Can you carry this for me?</td><td>Tista&#39; ġġorr dan għalija?</td></tr><tr><td style="text-align:right;">20</td><td>I need clean towels</td><td>Għandi bżonn xugamani nodfa</td></tr></tbody></table><h2 id="health-and-emergencies" tabindex="-1">Health and Emergencies <a class="header-anchor" href="#health-and-emergencies" aria-label="Permalink to &quot;Health and Emergencies&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>I don&#39;t feel well</td><td>Ma nħossnix tajjeb / tajba</td></tr><tr><td style="text-align:right;">2</td><td>I have a headache</td><td>Għandi uġigħ ta&#39; ras</td></tr><tr><td style="text-align:right;">3</td><td>I need a doctor</td><td>Għandi bżonn tabib</td></tr><tr><td style="text-align:right;">4</td><td>Where is the pharmacy?</td><td>Fejn hi l-ispiżerija?</td></tr><tr><td style="text-align:right;">5</td><td>I&#39;m allergic to ...</td><td>Jien allerġiku / allerġika għal ...</td></tr><tr><td style="text-align:right;">6</td><td>Call an ambulance, please</td><td>Ċempel ambulanza, jekk jogħġbok</td></tr><tr><td style="text-align:right;">7</td><td>Call the police, please</td><td>Ċempel lill-pulizija, jekk jogħġbok</td></tr><tr><td style="text-align:right;">8</td><td>I need help</td><td>Għandi bżonn l-għajnuna</td></tr><tr><td style="text-align:right;">9</td><td>I lost my wallet</td><td>Tlift il-kartiera tiegħi</td></tr><tr><td style="text-align:right;">10</td><td>Please call 112</td><td>Ċempel 112, jekk jogħġbok</td></tr><tr><td style="text-align:right;">11</td><td>I have a fever</td><td>Għandi d-deni</td></tr><tr><td style="text-align:right;">12</td><td>I need medicine</td><td>Għandi bżonn mediċina</td></tr><tr><td style="text-align:right;">13</td><td>Where is the nearest hospital?</td><td>Fejn hu l-eqreb sptar?</td></tr><tr><td style="text-align:right;">14</td><td>Call a doctor, please</td><td>Ċempel tabib, jekk jogħġbok</td></tr><tr><td style="text-align:right;">15</td><td>I have a stomach ache</td><td>Għandi uġigħ fl-istonku</td></tr><tr><td style="text-align:right;">16</td><td>I feel dizzy</td><td>Għandi sturdament</td></tr><tr><td style="text-align:right;">17</td><td>I lost my passport</td><td>Tlift il-passaport tiegħi</td></tr><tr><td style="text-align:right;">18</td><td>I need to go to the hospital</td><td>Għandi bżonn immur l-isptar</td></tr><tr><td style="text-align:right;">19</td><td>Help me, please</td><td>Għinni, jekk jogħġbok</td></tr><tr><td style="text-align:right;">20</td><td>I am allergic to nuts</td><td>Jien allerġiku / allerġika għall-ġewż</td></tr></tbody></table><h2 id="usage-notes" tabindex="-1">Usage Notes <a class="header-anchor" href="#usage-notes" aria-label="Permalink to &quot;Usage Notes&quot;">​</a></h2><ul><li><code>jekk jogħġbok</code> is commonly used in polite requests; the verb may need to change when addressing more than one person.</li><li>Adjectives may change according to the speaker&#39;s or noun&#39;s grammatical gender, for example <code>tajjeb</code> / <code>tajba</code> and <code>veġetarjan</code> / <code>veġetarjana</code>.</li><li>These are beginner examples. In conversation, choose the form that best fits the region, audience, and context.</li></ul>',24),l=[i];function n(s,g,h,o,y,x){return d(),e("div",null,l)}const k=t(r,[["render",n]]);export{u as __pageData,k as default};
